cssCode:
.nav-link {
  position: relative;
  text-decoration: none;
  color: #111;
  font-size: 35px;
  font-weight: 900;
  padding-bottom: 5px;
  cursor: pointer;
  font-family: sans-serif;
}
.nav-link::after {
  content: '';
  position: absolute;
  left: 0; bottom: 0;
  width: 0; height: 4px;
  background: #6c63ff;
  transition: width 0.4s cubic-bezier(0.25, 1, 0.5, 1);
}
.nav-link:hover::after {
  width: 100%;
}

